CREATE SEQUENCE public.seq_viewings_id
    START WITH 101
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.seq_viewings_id OWNER TO postgres;

--
-- Name: tasks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tasks (
    task_id character varying(64) DEFAULT ('task-'::text || (nextval('public.seq_tasks_id'::regclass))::text) NOT NULL,
    assigned_user_id character varying(64),
    customer_id character varying(64),
    lead_id character varying(64),
    opportunity_id character varying(64),
    title character varying(300) NOT NULL,
    due_at timestamp with time zone,
    priority character varying(20) DEFAULT 'NORMAL'::character varying NOT NULL,
    status character varying(30) DEFAULT 'OPEN'::character varying NOT NULL,
    template_id character varying(64),
    escalation_level integer DEFAULT 0,
    escalated_to_user_id character varying(64),
    created_at timestamp with time zone DEFAULT now(),
    completed_at timestamp with time zone,
    retry_count integer DEFAULT 0,
    parent_task_id character varying(64)
);


ALTER TABLE public.tasks OWNER TO postgres;

--
-- Name: tenancies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tenancies (
    tenancy_id character varying(64) DEFAULT ('tenancy-'::text || (nextval('public.seq_tenancies_id'::regclass))::text) NOT NULL,
    unit_id character varying(64) NOT NULL,
    tenant_customer_id character varying(64) NOT NULL,
    contract_number character varying(60) NOT NULL,
    start_date date NOT NULL,
    end_date date,
    rent_amount numeric(18,2) NOT NULL,
    payment_frequency character varying(20),
    deposit_amount numeric(18,2),
    status character varying(30) DEFAULT 'ACTIVE'::character varying NOT NULL,
    ejar_contract_number character varying(64),
    ejar_status character varying(32) DEFAULT 'ACTIVE'::character varying,
    contract_type character varying(32) DEFAULT 'RESIDENTIAL'::character varying,
    security_deposit_status character varying(32) DEFAULT 'HELD'::character varying,
    bank_name character varying(100),
    bank_iban character varying(50),
    bank_beneficiary character varying(150),
    maintenance_terms text,
    notes text,
    lead_id character varying(50),
    opportunity_id character varying(50)
);


ALTER TABLE public.tenancies OWNER TO postgres;

--
-- Name: unit_status_history; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.unit_status_history (
    unit_status_history_id character varying(64) DEFAULT ('unit_status_history-'::text || (nextval('public.seq_unit_status_history_id'::regclass))::text) NOT NULL,
    unit_id character varying(64) NOT NULL,
    old_status character varying(30),
    new_status character varying(30) NOT NULL,
    changed_by_user_id character varying(64),
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    reason character varying(500)
);


ALTER TABLE public.unit_status_history OWNER TO postgres;

--
-- Name: units; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.units (
    unit_id character varying(64) DEFAULT ('unit-'::text || (nextval('public.seq_units_id'::regclass))::text) NOT NULL,
    building_id character varying(64),
    unit_number character varying(50) NOT NULL,
    property_type_id character varying(64),
    floor_no smallint,
    area_sqm numeric(12,2),
    bedrooms smallint,
    bathrooms smallint,
    parking_spaces smallint,
    orientation character varying(50),
    asking_price numeric(18,2),
    rent_price numeric(18,2),
    status character varying(30) DEFAULT 'AVAILABLE'::character varying NOT NULL,
    owner_customer_id character varying(64),
    assigned_user_id character varying(64),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    project_id character varying(50),
    annual_operating_expenses numeric(12,2) DEFAULT 0.00,
    annual_vacancy_rate numeric(5,2) DEFAULT 0.00,
    investment_notes text,
    listing_purpose character varying(32) DEFAULT 'ALL'::character varying,
    total_floors smallint,
    CONSTRAINT ck_units_area CHECK (((area_sqm IS NULL) OR (area_sqm > (0)::numeric))),
    CONSTRAINT ck_units_prices CHECK ((((asking_price IS NULL) OR (asking_price >= (0)::numeric)) AND ((rent_price IS NULL) OR (rent_price >= (0)::numeric))))
);


ALTER TABLE public.units OWNER TO postgres;

--
-- Name: user_roles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.user_roles (
    user_id character varying(64) NOT NULL,
    role_id character varying(64) NOT NULL
);


ALTER TABLE public.user_roles OWNER TO postgres;

--
-- Name: users; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.users (
    user_id character varying(64) DEFAULT ('user-'::text || (nextval('public.seq_users_id'::regclass))::text) NOT NULL,
    organization_id character varying(64) NOT NULL,
    branch_id character varying(64),
    employee_no character varying(50),
    full_name character varying(200) NOT NULL,
    email character varying(254) NOT NULL,
    mobile character varying(30),
    status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    manager_user_id character varying(64),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    compensation_type character varying(32) DEFAULT 'COMMISSION'::character varying,
    base_salary numeric(12,2) DEFAULT 0.00,
    sales_commission_rate numeric(5,2) DEFAULT 25.00,
    rent_commission_rate numeric(5,2) DEFAULT 25.00,
    sales_fixed_cut numeric(12,2) DEFAULT 0.00,
    rent_fixed_cut numeric(12,2) DEFAULT 0.00
);


ALTER TABLE public.users OWNER TO postgres;

--
-- Name: vendors; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vendors (
    vendor_id character varying(64) DEFAULT ('vendor-'::text || (nextval('public.seq_vendors_id'::regclass))::text) NOT NULL,
    organization_id character varying(64) NOT NULL,
    vendor_name character varying(200) NOT NULL,
    phone character varying(30),
    email character varying(254),
    tax_number character varying(50),
    status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL
);


ALTER TABLE public.vendors OWNER TO postgres;

--
-- Name: viewings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.viewings (
    viewing_id character varying(64) DEFAULT ('viewing-'::text || (nextval('public.seq_viewings_id'::regclass))::text) NOT NULL,
    opportunity_id character varying(64) NOT NULL,
    unit_id character varying(64) NOT NULL,
    customer_id character varying(64) NOT NULL,
    agent_user_id character varying(64),
    scheduled_start timestamp with time zone NOT NULL,
    scheduled_end timestamp with time zone,
    status character varying(30) DEFAULT 'SCHEDULED'::character varying NOT NULL,
    outcome character varying(50),
    notes text,
    lead_id character varying(64),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT ck_viewing_time CHECK (((scheduled_end IS NULL) OR (scheduled_end >= scheduled_start)))
);


ALTER TABLE public.viewings OWNER TO postgres;

--
-- Name: workflow_sop_guidance; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflow_sop_guidance (
    guidance_id character varying(50) NOT NULL,
    stage_code character varying(50) NOT NULL,
    template_id character varying(50),
    stage_name_ar character varying(255) NOT NULL,
    stage_name_en character varying(255) NOT NULL,
    required_now_ar text NOT NULL,
    required_now_en text NOT NULL,
    current_responsible_ar character varying(255),
    current_responsible_en character varying(255),
    next_action_ar text NOT NULL,
    next_action_en text NOT NULL,
    step_goal_ar text NOT NULL,
    step_goal_en text NOT NULL,
    mandatory_conditions_ar text NOT NULL,
    mandatory_conditions_en text NOT NULL,
    consequence_ar text NOT NULL,
    consequence_en text NOT NULL,
    display_order integer DEFAULT 1,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    entity_type character varying(64) DEFAULT 'STAGE'::character varying,
    procedure_code character varying(64),
    responsible_role_code character varying(64),
    execution_steps_ar jsonb,
    execution_steps_en jsonb,
    sample_notes_ar text,
    sample_notes_en text
);


ALTER TABLE public.workflow_sop_guidance OWNER TO postgres;

--
-- Name: workflow_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflow_templates (
    template_id character varying(64) NOT NULL,
    template_type character varying(20) NOT NULL,
    standard_title_ar character varying(255) NOT NULL,
    standard_title_en character varying(255) NOT NULL,
    standard_subject_ar character varying(255),
    standard_subject_en character varying(255),
    owner_role character varying(50) NOT NULL,
    default_sla_minutes integer DEFAULT 30,
    escalation_role character varying(50),
    escalation_sla_minutes integer,
    created_at timestamp with time zone DEFAULT now(),
    next_template_id character varying(100),
    outcome_transitions jsonb,
    completion_criteria_ar text,
    completion_criteria_en text
);


ALTER TABLE public.workflow_templates OWNER TO postgres;

